      waits: flag.waits,
      why: flag.why,
      notRead: flag.notRead ?? null,
      marks: [{ kind: 'bar', from: ms(pr.created_at), to: now, flag: flag.waits }],
    };
  }).sort((a, b) => (b.waits ? 1 : 0) - (a.waits ? 1 : 0) || a.openedAt - b.openedAt);

